<template>
 <section class="qvl-page" :aria-label="vt(&quot;我的声音收藏室&quot;)">
  <header class="qvl-hero">
   <div class="qvl-hero-copy"><span class="qvl-eyebrow">QGAUSS / KEEP A LITTLE RESONANCE</span><h1>{{ vt("让好声音，") }}<br><mark>{{ vt("有下一次相遇。") }}</mark></h1><p>{{ vt("说过的灵感，配音与朗读。") }}<br>{{ vt("收进自己的声音收藏室，随时回来听一听。") }}</p><div class="qvl-hero-actions"><router-link class="qvl-primary" to="/voice/create">{{ vt("写一段自己的声音") }} <span>↗</span></router-link><router-link class="qvl-primary" to="/chat?voice=record"><ClientIcon name="microphone"/>{{ vt("去对话，录一段") }} <span>↗</span></router-link><router-link to="/chat?voice=voices">{{ vt("发现一种新声音") }} <span>▷</span></router-link></div></div>
   <div class="qvl-sculpture" aria-hidden="true"><div class="qvl-orbit"></div><div class="qvl-record"><i></i><b>Q</b><span v-for="n in 14" :key="n" :style="{'--bar':n}"></span></div><em>✦</em><small>GOOD WORDS.<br>BETTER IN YOUR EARS.</small><div class="qvl-satellite">♪</div></div>
  </header>
  <div class="qvl-policy"><span class="qvl-policy-mark">✳</span><p><b>{{ policyDays===null?vt("作品保存规则待核对"):policyDays>0?vt('新作品默认保留 {days} 天',{days:policyDays}):vt("新作品默认保留至主动清理") }}</b><small>{{ vt("已保存的作品沿用当时的规则。重新播放不再次生成，也不再次扣减次数。") }}</small></p><router-link v-if="auth.isAdmin" to="/voice/manage">{{ vt("管理保存规则 ↗") }}</router-link></div>
  <div v-if="pendingDelete" class="qvl-recovery" role="status"><p>{{ vt("有一次清理的结果还未确认。先核对原记录，再进行下一次清理。") }}</p><button type="button" :disabled="deleting" @click="checkRemoval">{{ vt("核对原清理结果 ↗") }}</button></div>
  <div v-if="pendingStop" class="qvl-recovery" role="status"><p>{{ vt("有一次停止的结果还未确认。先同步原任务，不会再提交一次生成。") }}</p><button type="button" :disabled="deleting" @click="checkStop">{{ vt("核对原停止结果 ↻") }}</button></div>
  <p v-if="notice" class="qvl-notice" role="status">{{ vt(notice) }}</p><p v-if="error" class="qvl-error" role="alert">{{ vt(error) }}</p>
  <div class="qvl-workspace">
   <section class="qvl-library" aria-labelledby="qvl-library-title">
    <div class="qvl-library-heading"><div><span class="qvl-eyebrow">YOUR PRIVATE LISTENING ROOM</span><h2 id="qvl-library-title" ref="libraryHeading" tabindex="-1">{{ vt("每一次回响，都在这里。") }}</h2></div><button type="button" class="qvl-refresh" :disabled="loading||deleting" @click="refresh"><ClientIcon name="refresh"/>{{ vt("刷新记录") }}</button></div>
    <form class="qvl-search" role="search" @submit.prevent="search"><ClientIcon name="search"/><input v-model="query" type="search" maxlength="100" :aria-label="vt(&quot;搜索声音记录&quot;)" :placeholder="vt(&quot;找一句话、一段声音，或一种音色&quot;)"/><button type="submit" :disabled="loading||deleting">{{ vt("找一找 ↗") }}</button></form>
    <div class="qvl-filters"><div class="qvl-tabs" :aria-label="vt(&quot;声音类型&quot;)"><button v-for="item in kinds" :key="item.id" type="button" :aria-pressed="kind===item.id" :disabled="deleting" @click="filter(item.id)">{{ vt(item.title) }}<span v-if="item.id==='all'">{{ counts.all }}</span></button></div><label class="qvl-state-filter"><span class="qvl-sr">{{ vt("声音记录状态") }}</span><select v-model="state" :aria-label="vt(&quot;筛选声音状态&quot;)" :disabled="deleting" @change="page=1;load()"><option value="all">{{ vt("全部状态") }}</option><option value="completed">{{ vt("已经完成") }}</option><option value="processing">{{ vt("正在处理") }}</option><option value="failed">{{ vt("未能完成") }}</option><option value="canceled">{{ vt("已经停止") }}</option><option value="expired">{{ vt("已过保留期限") }}</option></select></label></div>
    <BrandLoader v-if="loading" :size="42" :text="vt(&quot;正在集合你的声音足迹…&quot;)"/>
    <div v-else-if="loadError" class="qvl-empty" role="alert"><span>☁</span><h3>{{ vt("这次，声音还没抵达。") }}</h3><p>{{ vt(loadError) }}</p><button type="button" class="qvl-primary" @click="load">{{ vt("再取一次 ↻") }}</button></div>
    <div v-else-if="!items.length" class="qvl-empty"><span>{{ query.trim()?'⌕':'♫' }}</span><h3>{{ query.trim()?vt("换个词，让声音回应你。"):vt("给下一次灵感，留一个声音的位置。") }}</h3><p>{{ query.trim()?vt("试试文字片段或音色名称。"):vt("在对话中录音转文字，或让一条完整回答读给你听，记录就会出现在这里。") }}</p><button v-if="query.trim()||kind!=='all'||state!=='all'" type="button" class="qvl-primary" @click="resetFilters">{{ vt("看看全部记录 ↗") }}</button><router-link v-else class="qvl-primary" to="/chat?voice=record">{{ vt("去对话，说出第一段灵感 ↗") }}</router-link></div>
    <div v-else class="qvl-grid"><article v-for="(row,index) in items" :key="row.id" class="qvl-card" :class="['qvl-tone-'+tone(row),{'is-selected':selected?.id===row.id}]" :style="{'--qvl-order':index%12}"><button type="button" class="qvl-card-open" :aria-label="vt('打开声音记录：{title}',{title:title(row)})" :aria-pressed="selected?.id===row.id" :disabled="deleting" @click="open(row)"><div class="qvl-card-art" aria-hidden="true"><div class="qvl-card-disc"><span>{{ row.kind==='transcription'?'✳':'♪' }}</span></div><i v-for="n in 15" :key="n" :style="{'--wave':n,'--wave-size':12+(Math.sin(n*1.9+index)**2)*27+'px'}"></i><small>{{ row.kind==='transcription'?'A THOUGHT, CAPTURED':'A VOICE, KEPT CLOSE' }}</small></div><span class="qvl-card-meta">{{ row.kind==='transcription'?vt("录音转写"):row.sample?vt("音色试听"):row.sourceKind==='composition'?vt("文字配音"):vt("回答朗读") }}<b :class="{'is-processing':row.availability==='processing'}">{{ vt(stateLabel(row)) }}</b></span><h3>{{ title(row) }}</h3><p>{{ row.availability==='expired'?vt("保留期限已过，内容不再开放。"):row.availability==='unavailable'?vt("打开记录，查看原因与费用回执。"):row.kind==='transcription'?vt("把说过的灵感，重新握在手里。"):vt('{voice} · {count} 段声音',{voice:vt(voiceName(row.voice)),count:row.segmentCount}) }}</p><footer><time :datetime="row.createdAt">{{ date(row.createdAt) }}</time><span>{{ vt("打开看看 ↗") }}</span></footer></button></article></div>
    <nav v-if="!loading&&!loadError&&total" class="qvl-pager" :aria-label="vt(&quot;声音记录分页&quot;)"><button type="button" :disabled="page<=1||deleting" @click="page--;load()">{{ vt("← 上一页") }}</button><span>{{ vt("{p0} 段足迹 · 第 {p1} 页",{p0:total,p1:page}) }}</span><button type="button" :disabled="page*pageSize>=total||deleting" @click="page++;load()">{{ vt("下一页 →") }}</button></nav>
   </section>
   <aside class="qvl-detail" :aria-label="vt(&quot;声音记录详情&quot;)"><BrandLoader v-if="detailLoading&&!selected" :size="34" :text="vt(&quot;正在打开这一次回响…&quot;)"/><p v-else-if="!selected" class="qvl-detail-empty"><span>↖</span>{{ vt("选一段声音，") }}<br>{{ vt("把好想法，再听一遍。") }}</p><template v-else><header><span class="qvl-eyebrow">ONE GOOD MOMENT, AGAIN</span><h2 ref="detailHeading" tabindex="-1">{{ title(selected) }}</h2><p>{{ vt(stateLabel(selected)) }} · {{ date(selected.createdAt) }}</p></header>
    <div class="qvl-player-art" :class="{'is-playing':playing}" aria-hidden="true"><div><span>{{ selected.kind==='transcription'?'✳':'♪' }}</span></div><i></i><i></i><i></i></div>
    <p v-if="selected.availability==='processing'" class="qvl-info" role="status">{{ vt("{p0}。这里只同步原任务，不会再提交一次。",{p0:vt(voiceTaskLabel(selected))}) }}</p>
    <p v-else-if="selected.availability!=='ready'" class="qvl-info" role="status">{{ vt(selected.availabilityReason)||vt("这份内容当前无法读取，原有费用回执仍可查看。") }}</p>
    <div v-if="selected.kind==='speech'&&selected.availability==='ready'" class="qvl-player"><button type="button" class="qvl-play" :disabled="audioLoading||deleting" :aria-label="playing?vt(&quot;暂停这段声音&quot;):vt(&quot;播放这段声音&quot;)" @click="togglePlay"><BrandLoader v-if="audioLoading" :size="26"/><span v-else>{{ playing?'Ⅱ':'▶' }}</span></button><div><b>{{ vt("{p0} · 第 {p1} / {p2} 段",{p0:vt(voiceName(selected.voice)),p1:part+1,p2:selected.audio.length}) }}</b><p>{{ voiceDuration(playbackSeconds) }} / {{ voiceDuration(playbackDuration) }}</p></div><div class="qvl-part-buttons"><button type="button" :aria-label="vt(&quot;上一段声音&quot;)" :disabled="part===0||audioLoading||deleting" @click="playPart(part-1)">‹</button><button type="button" :aria-label="vt(&quot;下一段声音&quot;)" :disabled="part+1>=selected.audio.length||audioLoading||deleting" @click="playPart(part+1)">›</button></div><input type="range" min="0" :max="playbackDuration||0" :value="playbackSeconds" step="0.1" :aria-label="vt(&quot;声音播放进度&quot;)" :disabled="!audioUrl||!playbackDuration" @input="seek($event.target.value)"/><small>{{ vt("播放已保存的音频，不会再次生成或扣减次数。") }}</small></div>
    <audio ref="audioElement" :src="audioUrl||undefined" preload="none" @loadedmetadata="metadata" @timeupdate="timeUpdate" @ended="nextPart" @error="audioError"></audio>
    <section v-if="selected.kind==='transcription'&&selected.availability==='ready'" class="qvl-transcript"><h3>{{ vt("那一刻，你说了这些。") }}</h3><textarea :value="selected.transcript" readonly rows="7" :aria-label="vt(&quot;历史转写文字&quot;)"/><div><button type="button" :disabled="deleting" @click="copyTranscript">{{ vt("复制文字") }}</button><button type="button" class="qvl-primary" :disabled="deleting" @click="takeToChat">{{ vt("带去对话 ↗") }}</button></div><small>{{ vt("进入对话后可以继续修改，发送由你决定。") }}</small></section>
    <section v-if="selected.sourceKind==='composition'&&selected.sourceText" class="qvl-transcript"><h3>{{ vt("这一次，你写下了这些。") }}</h3><textarea :value="selected.sourceText" readonly rows="7" :aria-label="vt(&quot;已保存的配音文字&quot;)"/><button type="button" class="qvl-primary" :disabled="deleting" @click="takeToComposer">{{ vt("用这段文字再配音 ↗") }}</button><small>{{ vt("带入工作室后可以继续编辑，生成前会再次确认。") }}</small></section><button v-if="selected.kind==='speech'&&selected.availability==='ready'" type="button" class="qvl-secondary qvl-wide" :disabled="deleting||downloading" @click="downloadComplete">{{ downloading?vt("正在整理整段声音…"):vt("保存完整声音") }}</button><router-link v-if="selected.conversationId" class="qvl-conversation-link" :to="{path:'/chat',query:{conversation:selected.conversationId}}">{{ vt("回到这段声音的原对话 ↗") }}</router-link>
    <p v-if="playerError" class="qvl-error" role="alert">{{ vt(playerError) }}</p>
    <dl class="qvl-receipt"><div><dt>{{ vt("本站次数") }}</dt><dd>{{ billing(selected) }}</dd></div><div><dt>{{ vt("内容保存") }}</dt><dd>{{ selected.expiresAt?vt('保留至 {date}',{date:date(selected.expiresAt)}):vt("保留至主动清理") }}</dd></div></dl>
    <button v-if="selected.availability==='processing'" type="button" class="qvl-secondary qvl-wide" :disabled="detailLoading||deleting" @click="refreshSelected">{{ vt("同步原任务 ↻") }}</button><button v-if="selected.availability==='processing'&&selected.status!=='SETTLING'" type="button" class="qvl-remove" :disabled="deleting||!!pendingDelete||!!pendingStop" @click="askStop(selected)">{{ vt("停止这次生成") }}</button><button v-else-if="selected.availability!=='processing'" type="button" class="qvl-remove" :disabled="deleting||!!pendingDelete||!!pendingStop" @click="askRemove(selected)">{{ vt("清理这条记录") }}</button>
   </template></aside>
  </div>
  <dialog ref="removeDialog" class="qvl-dialog" aria-labelledby="qvl-remove-title" @cancel.prevent="!deleting&&removeDialog.close()"><span class="qvl-eyebrow">A LITTLE SPACE FOR WHAT COMES NEXT</span><h2 id="qvl-remove-title">{{ actionMode==='stop'?vt("先让这次声音，停在这里？"):vt("让这一次回响，轻轻退场？") }}</h2><p>{{ removalTarget?.label||vt("这条声音记录") }}</p><p>{{ actionMode==='stop'?vt("会结束本站的这次生成并释放可退回的预留次数。结果已经保存、开始结算时无法再停止；服务方是否继续计费，以其账单为准。"):vt("记录会从收藏室移除，内容停止开放，文件在后台清理。这一步不能撤销，已结算的次数和费用回执会保留。") }}</p><div><button type="button" :disabled="deleting" @click="removeDialog.close()">{{ vt("再留一会儿") }}</button><button type="button" class="qvl-primary" :disabled="deleting" @click="actionMode==='stop'?stopTask():remove()"><BrandLoader v-if="deleting" :size="20"/>{{ deleting?vt("正在处理…"):actionMode==='stop'?vt("确认停止这次生成"):vt("确认清理这条记录") }}</button></div></dialog>
 </section>
</template>

<script setup>
import {voiceText as vt,voiceLocale} from "../../i18n/voice.js";
import {nextTick,onBeforeUnmount,onMounted,ref,reactive,watch} from 'vue';
import {onBeforeRouteLeave,useRouter} from 'vue-router';
import {api,fetchBlob} from '../../api/client.js';
import {transferVoiceComposition} from '../../lib/voice-composer-state.js';
import {useAuth} from '../../stores/auth.js';
import {voiceName,voiceDuration,voiceTaskLabel,voiceBilling} from '../../lib/voice-presentation.js';
import ClientIcon from '../reference/ClientIcon.vue';
import BrandLoader from './BrandLoader.vue';
import './voice-library.css';
const downloading=ref(false);
const auth=useAuth(),router=useRouter(),items=ref([]),counts=reactive({all:0,speech:0,transcription:0}),kind=ref('all'),state=ref('all'),query=ref(''),committedQuery=ref(''),page=ref(1),pageSize=9,total=ref(0),policyDays=ref(null);
const loading=ref(false),loadError=ref(''),detailLoading=ref(false),selected=ref(null),error=ref(''),notice=ref(''),deleting=ref(false),pendingDelete=ref(''),pendingStop=ref(''),actionMode=ref('remove'),removalTarget=ref(null),removeDialog=ref(null),libraryHeading=ref(null),detailHeading=ref(null);
const audioElement=ref(null),audioUrl=ref(''),audioLoading=ref(false),playing=ref(false),part=ref(0),playbackSeconds=ref(0),playbackDuration=ref(0),playerError=ref('');
const kinds=[{id:'all',title:'全部声音'},{id:'speech',title:'配音与朗读'},{id:'transcription',title:'说过的好想法'}];
let alive=true,epoch=0,listRevision=0,detailRevision=0,playRevision=0,pollTimer=null;const controllers=new Map();
const stamp=()=>({id:auth.user?.id,identity:auth.identityRevision,epoch}),current=s=>alive&&auth.isLoggedIn&&s.id===auth.user?.id&&s.identity===auth.identityRevision&&s.epoch===epoch;
function request(key){controllers.get(key)?.abort();const controller=new AbortController();controllers.set(key,controller);return{signal:AbortSignal.any([controller.signal,AbortSignal.timeout(20000)]),current:()=>controllers.get(key)===controller&&!controller.signal.aborted};}
function valid(row,full=false){
 if(!row||typeof row.id!=='string'||!row.id||row.id.length>128||!['speech','transcription'].includes(row.kind)||!['ready','processing','expired','unavailable'].includes(row.availability)||!row.billing||!['reserved','charged','returned','expired'].every(key=>Number.isFinite(row.billing[key])&&row.billing[key]>=0))throw Error('声音资料不完整，请刷新后再试。');
 if(full&&(!Array.isArray(row.audio)||typeof row.transcript!=='string'||row.kind==='speech'&&row.availability==='ready'&&!row.audio.length||!row.audio.every((file,index)=>file.index===index&&file.url==='/api/voice/tasks/'+encodeURIComponent(row.id)+'/audio/'+index)))throw Error('声音文件资料不完整，请刷新后再试。');return row;
}
const title=row=>row.label||vt(row.kind==='transcription'?'留在这里的一段灵感':row.sample?'一次音色试听':row.sourceKind==='composition'?'一段文字配音':'一段回答朗读');
const date=value=>{const time=new Date(value);return Number.isFinite(time.getTime())?new Intl.DateTimeFormat(voiceLocale(),{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit',hour12:false}).format(time):vt('时间待确认');};
const stateLabel=row=>row.availability==='expired'?'已到期':({COMPLETED:row.availability==='ready'?row.kind==='transcription'?'文字已留好':'可以再听听':'内容不可用',QUEUED:'排队中',RUNNING:'进行中',SETTLING:'保存与结算中',FAILED:'未能完成',CANCELED:'已经停止'})[row.status]||'等待核对';
const billing=row=>voiceBilling(row.billing,vt);
function tone(row){let hash=0;for(const char of row.id)hash=(hash*31+char.charCodeAt(0))>>>0;return['violet','peach','mint'][hash%3];}
function remember(id){pendingDelete.value=id;try{id?sessionStorage.setItem('qg:voice-remove:'+auth.user?.id,id):sessionStorage.removeItem('qg:voice-remove:'+auth.user?.id);}catch{notice.value='临时核对记录未能保留，请在本页确认清理结果后再离开。';}}
function stopPlayback(){playRevision++;controllers.get('audio')?.abort();const audio=audioElement.value;audio?.pause();audio?.removeAttribute('src');audio?.load();if(audioUrl.value)URL.revokeObjectURL(audioUrl.value);audioUrl.value='';playing.value=false;audioLoading.value=false;playbackSeconds.value=0;playbackDuration.value=0;}
async function load(){const s=stamp(),revision=++listRevision,req=request('list');loading.value=true;loadError.value='';const params=new URLSearchParams({page:String(page.value),pageSize:String(pageSize),kind:kind.value,state:state.value,...(committedQuery.value?{q:committedQuery.value}:{})});try{const data=await api.get('/voice/library?'+params,{signal:req.signal,retry:false});if(current(s)&&req.current()&&revision===listRevision){items.value=Array.isArray(data.items)?data.items.map(row=>valid(row)):[];total.value=data.total;policyDays.value=Number.isInteger(data.policy?.retentionDays)&&data.policy.retentionDays>=0&&data.policy.retentionDays<=3650?data.policy.retentionDays:null;Object.assign(counts,data.counts);if(page.value>1&&!items.value.length&&total.value>0){page.value=Math.ceil(total.value/pageSize);void load();}}}catch(e){if(current(s)&&req.current()&&revision===listRevision)loadError.value=e.message;}finally{if(current(s)&&req.current()&&revision===listRevision)loading.value=false;}}
async function focusDetail({reveal=false}={}){await nextTick();if(!alive)return;const target=detailHeading.value||libraryHeading.value;target?.focus({preventScroll:true});if(reveal){const panel=detailHeading.value?.closest('.qvl-detail');panel?.scrollTo?.({top:0});(panel||target)?.scrollIntoView?.({block:'start',behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});}}
async function open(row,{refresh=false}={}){if(deleting.value)return;const s=stamp(),revision=++detailRevision,req=request('detail');clearTimeout(pollTimer);if(!refresh){stopPlayback();selected.value=null;part.value=0;}detailLoading.value=true;error.value='';try{const data=valid(await api.get('/voice/library/'+encodeURIComponent(row.id),{signal:req.signal,retry:false}),true);if(!current(s)||!req.current()||revision!==detailRevision)return;if(data.availability!=='ready')stopPlayback();selected.value=data;if(!refresh)await focusDetail({reveal:true});if(data.availability==='processing')pollTimer=setTimeout(()=>{if(current(s)&&selected.value?.id===data.id)void open(data,{refresh:true});},1500);}catch(e){if(current(s)&&req.current()&&revision===detailRevision){stopPlayback();selected.value=null;error.value=e.status===404?'这条记录已被清理或当前不可用。':e.message;await focusDetail();}}finally{if(current(s)&&req.current()&&revision===detailRevision)detailLoading.value=false;}}
function refreshSelected(){if(selected.value)void open(selected.value,{refresh:true});}
async function refresh(){const s=stamp();await load();if(current(s)&&selected.value)await open(selected.value,{refresh:true});}
function filter(value){if(deleting.value||kind.value===value)return;kind.value=value;page.value=1;void load();}
function search(){committedQuery.value=query.value.trim();page.value=1;void load();}
function resetFilters(){query.value=committedQuery.value='';kind.value=state.value='all';page.value=1;void load();}
async function playPart(index){const row=selected.value;if(deleting.value||row?.availability!=='ready'||row.kind!=='speech'||!Number.isInteger(index)||index<0||index>=row.audio.length)return;stopPlayback();part.value=index;const s=stamp(),revision=playRevision,req=request('audio');audioLoading.value=true;playerError.value='';try{const blob=await fetchBlob(row.audio[index].url,{signal:req.signal,retry:false});if(!current(s)||!req.current()||revision!==playRevision||selected.value?.id!==row.id)return;audioUrl.value=URL.createObjectURL(blob);await nextTick();if(!current(s)||revision!==playRevision)return;await audioElement.value.play();if(current(s)&&revision===playRevision)playing.value=true;}catch(e){if(current(s)&&req.current()&&revision===playRevision){playing.value=false;playerError.value=e.name==='NotAllowedError'?'声音已准备好，请再点一次播放。':e.status===404?'音频已到期、被清理或暂不可用。这里不会重新生成。':e.message||'暂时没有播放成功，请再试一次。';}}finally{if(current(s)&&req.current()&&revision===playRevision)audioLoading.value=false;}}
async function togglePlay(){if(playerError.value&&!playing.value){await playPart(part.value);return;}if(playing.value){audioElement.value.pause();playing.value=false;return;}if(audioUrl.value){const s=stamp(),revision=playRevision;try{await audioElement.value.play();if(current(s)&&revision===playRevision)playing.value=true;}catch{if(current(s)&&revision===playRevision)playerError.value='请再点一次播放。';}return;}await playPart(part.value);}
function metadata(){playbackDuration.value=Number.isFinite(audioElement.value?.duration)?audioElement.value.duration:0;}
function timeUpdate(){playbackSeconds.value=audioElement.value?.currentTime||0;}
function seek(value){const seconds=Number(value);if(audioElement.value&&Number.isFinite(seconds))audioElement.value.currentTime=Math.max(0,Math.min(seconds,playbackDuration.value));}
function nextPart(){if(selected.value?.audio?.[part.value+1])void playPart(part.value+1);else{playing.value=false;playbackSeconds.value=0;if(audioElement.value)audioElement.value.currentTime=0;}}
function audioError(){if(audioUrl.value){playing.value=false;playerError.value='这段声音暂时无法播放，请重新选择分段；不会重新生成。';}}
async function copyTranscript(){const s=stamp(),text=selected.value?.transcript;if(!text)return;try{await navigator.clipboard.writeText(text);if(current(s))notice.value='文字已复制。';}catch{if(current(s))error.value='暂时无法复制，请检查浏览器的剪贴板设置。';}}
function takeToComposer(){const row=selected.value;if(!row?.sourceText||deleting.value)return;try{transferVoiceComposition(auth.user.id,{title:row.label||'',text:row.sourceText,voice:row.voice});void router.push('/voice/create');}catch(e){error.value=e.message;}}
async function downloadComplete(){const row=selected.value,s=stamp();if(!row||row.availability!=='ready'||row.kind!=='speech'||downloading.value||deleting.value)return;downloading.value=true;const req=request('download');try{const blob=await fetchBlob('/api/voice/tasks/'+encodeURIComponent(row.id)+'/download',{signal:req.signal});if(!current(s)||!req.current()||selected.value?.id!==row.id)return;const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=('QGauss-'+(row.label||'声音作品')).replace(/[\\/:*?"<>|\u0000-\u001f]/g,'_').slice(0,100)+'.mp3';document.body.appendChild(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);notice.value='完整声音已整理，可以在浏览器下载中找到。';}catch(e){if(current(s)&&req.current()&&e.name!=='AbortError')error.value=e.message||'完整声音暂时未能保存，可以继续分段重听。';}finally{if(current(s))downloading.value=false;}}
function takeToChat(){if(selected.value?.kind==='transcription'&&selected.value.availability==='ready')void router.push({path:'/chat',query:{voiceTask:selected.value.id}});}
function askRemove(row){if(deleting.value||pendingDelete.value||pendingStop.value||row.availability==='processing')return;actionMode.value='remove';removalTarget.value=row;removeDialog.value?.showModal();}
async function remove(){const row=removalTarget.value;if(!row||deleting.value)return;const s=stamp(),req=request('remove');deleting.value=true;error.value='';remember(row.id);try{await api.del('/voice/library/'+encodeURIComponent(row.id),{signal:req.signal,retry:false});if(!current(s))return;remember('');removeDialog.value?.close();removalTarget.value=null;if(selected.value?.id===row.id){stopPlayback();selected.value=null;}notice.value='记录已移除，内容停止开放；文件将在后台清理。';await load();await focusDetail();}catch(e){if(current(s)){removeDialog.value?.close();error.value=e.message;if(e.status>=400&&e.status<500&&![408,429].includes(e.status))remember('');else notice.value='清理结果尚未确认，请先核对原记录。';await focusDetail();}}finally{if(current(s))deleting.value=false;}}
async function checkRemoval(){if(!pendingDelete.value||deleting.value)return;const id=pendingDelete.value,s=stamp(),req=request('recovery');deleting.value=true;error.value='';try{const row=valid(await api.get('/voice/library/'+encodeURIComponent(id),{signal:req.signal,retry:false}));if(current(s)){actionMode.value='remove';removalTarget.value=row;notice.value='原记录仍在，可以再次确认清理同一条记录。';removeDialog.value?.showModal();}}catch(e){if(current(s)){if(e.status===404){remember('');removalTarget.value=null;if(selected.value?.id===id){stopPlayback();selected.value=null;}notice.value='原记录已清理，没有重复生成或扣费。';await load();await focusDetail();}else error.value=e.message;}}finally{if(current(s))deleting.value=false;}}
function rememberStop(id){pendingStop.value=id;try{id?sessionStorage.setItem('qg:voice-stop:'+auth.user?.id,id):sessionStorage.removeItem('qg:voice-stop:'+auth.user?.id);}catch{notice.value='停止结果的临时核对记录未能保存，请在本页同步结果后再离开。';}}
function askStop(row){if(deleting.value||pendingDelete.value||pendingStop.value||row.availability!=='processing'||row.status==='SETTLING')return;actionMode.value='stop';removalTarget.value=row;removeDialog.value?.showModal();}
async function stopTask(){
 const row=removalTarget.value;if(!row||deleting.value)return;const s=stamp(),req=request('stop');deleting.value=true;error.value='';rememberStop(row.id);
 try{const result=await api.post('/voice/tasks/'+encodeURIComponent(row.id)+'/cancel',{}, {signal:req.signal,retry:false});if(!current(s))return;
  if(['COMPLETED','FAILED','CANCELED','SETTLING'].includes(result?.status))rememberStop('');removeDialog.value?.close();
  notice.value=result.status==='CANCELED'?'已停止生成，次数处理结果保留在回执中。':result.status==='SETTLING'||result.status==='COMPLETED'?'结果已经保存，将按完成的结果结算；没有再次生成。':'已收到当前任务状态，请同步原回执。';
  const detail=valid(await api.get('/voice/library/'+encodeURIComponent(row.id),{signal:req.signal,retry:false}),true);if(!current(s))return;if(selected.value?.id===row.id){if(detail.availability!=='ready')stopPlayback();selected.value=detail;}await load();await focusDetail();
 }catch(e){if(current(s)){removeDialog.value?.close();error.value=e.message;if(e.status>=400&&e.status<500&&![408,429].includes(e.status))rememberStop('');if(pendingStop.value)notice.value='停止结果尚未确认，请先同步原任务；不会重新提交生成。';await focusDetail();}}
 finally{if(current(s))deleting.value=false;}
}
async function checkStop(){
 if(!pendingStop.value||deleting.value)return;const id=pendingStop.value,s=stamp(),req=request('stop-recovery');deleting.value=true;error.value='';
 try{const row=valid(await api.get('/voice/library/'+encodeURIComponent(id),{signal:req.signal,retry:false}),true);if(!current(s))return;
  if(row.availability==='processing'&&row.status!=='SETTLING'){actionMode.value='stop';removalTarget.value=row;notice.value='原任务仍在处理，可以再次明确停止同一项任务。';removeDialog.value?.showModal();}
  else{rememberStop('');if(selected.value?.id===id){if(row.availability!=='ready')stopPlayback();selected.value=row;}notice.value=row.status==='CANCELED'?'原任务已停止，没有再次退款或生成。':row.status==='SETTLING'?'结果已保存，正在完成结算，此时无法再停止。':'已找回原任务的最终回执，没有重复执行。';await load();}
 }catch(e){if(current(s)){if(e.status===404){rememberStop('');if(selected.value?.id===id){stopPlayback();selected.value=null;}notice.value='原记录当前不可用，没有重新提交任务。';}else error.value=e.message;}}
 finally{if(current(s))deleting.value=false;}
}
function protectWork(event){if(deleting.value){event.preventDefault();event.returnValue='';}}
async function bootstrap(){try{const id=sessionStorage.getItem('qg:voice-remove:'+auth.user?.id);pendingDelete.value=typeof id==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(id)?id:'';const stop=sessionStorage.getItem('qg:voice-stop:'+auth.user?.id);pendingStop.value=typeof stop==='string'&&/^[A-Za-z0-9_-]{1,128}$/.test(stop)?stop:'';}catch{}await load();}
watch([()=>auth.user?.id,()=>auth.identityRevision],()=>{epoch++;listRevision++;detailRevision++;for(const controller of controllers.values())controller.abort();controllers.clear();clearTimeout(pollTimer);stopPlayback();removeDialog.value?.close();items.value=[];selected.value=null;pendingDelete.value='';pendingStop.value='';actionMode.value='remove';removalTarget.value=null;notice.value=error.value=loadError.value='';loading.value=detailLoading.value=deleting.value=downloading.value=false;Object.assign(counts,{all:0,speech:0,transcription:0});total.value=0;policyDays.value=null;query.value=committedQuery.value='';kind.value=state.value='all';page.value=1;if(auth.isLoggedIn)void bootstrap();});
onBeforeRouteLeave(()=>!deleting.value);onMounted(()=>{window.addEventListener('beforeunload',protectWork);void bootstrap();});onBeforeUnmount(()=>{alive=false;epoch++;for(const controller of controllers.values())controller.abort();controllers.clear();clearTimeout(pollTimer);stopPlayback();window.removeEventListener('beforeunload',protectWork);});
</script>
